package me.minis.ledger;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.widget.RemoteViews;import java.util.*;import java.util.concurrent.*;
/** Standard launcher widget. No network, wake lock or frequent polling. */
public final class LedgerWidget extends AppWidgetProvider {
 private static final ScheduledThreadPoolExecutor worker=new ScheduledThreadPoolExecutor(1);
 private static final WidgetWork work=new WidgetWork(worker);
 private static final java.util.concurrent.atomic.AtomicLong selection=new java.util.concurrent.atomic.AtomicLong();
 private static ScheduledFuture<?> pendingChange;
 static{worker.setRemoveOnCancelPolicy(true);}
 private static int dp(Context c,int value){return Math.round(value*c.getResources().getDisplayMetrics().density);}
 private static int id(Context c,String type,String name){return c.getResources().getIdentifier(name,type,c.getPackageName());}
 public static synchronized void changed(Context c){Context app=c.getApplicationContext();if(AppWidgetManager.getInstance(app).getAppWidgetIds(new ComponentName(app,LedgerWidget.class)).length==0||pendingChange!=null)return;pendingChange=worker.schedule(()->{synchronized(LedgerWidget.class){pendingChange=null;}work.submit(v->updateAll(app,-1,v,selection.get()),null);},300,TimeUnit.MILLISECONDS);}
 private static void updateAll(Context c,int target,long version,long state){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=target<0?m.getAppWidgetIds(new ComponentName(c,LedgerWidget.class)):new int[]{target};Map<String,long[]> totals=new HashMap<>();long now=System.currentTimeMillis();if(ids.length==0||!work.current(version))return;try(LedgerDb db=new LedgerDb(c)){Map<Boolean,BudgetUsage> budgets=new HashMap<>();try(StatsSnapshot snapshot=new StatsSnapshot(db.getReadableDatabase())){for(int widget:ids){if(!work.current(version)||state!=selection.get())return;boolean net=LedgerDb.prefs(c).getBoolean("widget_net_"+widget,false);if(!budgets.containsKey(net))budgets.put(net,BudgetUsage.read(c,now,net,snapshot));int period=WidgetPeriods.valid(LedgerDb.prefs(c).getInt("widget_period_"+widget,0));String key=period+"|"+net;if(!totals.containsKey(key))totals.put(key,db.widgetTotals(now,period,net,snapshot));}}for(int widget:ids){if(!work.current(version)||state!=selection.get())return;update(c,m,widget,totals,now,budgets,db,version,state);}}catch(Exception e){LedgerDb.prefs(c).edit().putString("widget_error","桌面组件更新失败，请打开轻记后刷新").apply();}}
 static void applyTheme(Context c,RemoteViews v,boolean dark){String suffix=dark?"_dark":"";String[][] backgrounds={{"widget_root","widget_bg"},{"widget_history","widget_history_bg"},{"widget_periods","widget_period_bg"},{"widget_mode","widget_chip"}};for(String[] b:backgrounds)v.setInt(id(c,"id",b[0]),"setBackgroundResource",id(c,"drawable",b[1]+suffix));v.setTextColor(id(c,"id","widget_amount"),AppAppearance.text(dark));v.setTextColor(id(c,"id","widget_mode"),AppAppearance.accent(dark));for(String name:new String[]{"widget_caption","widget_previous","widget_earlier"})v.setTextColor(id(c,"id",name),AppAppearance.muted(dark));v.setInt(id(c,"id","widget_refresh"),"setColorFilter",AppAppearance.accent(dark));}
 private static PendingIntent action(Context c,int widget,String action){Intent i=new Intent(c,LedgerWidget.class).addFlags(Intent.FLAG_RECEIVER_FOREGROUND).setAction("me.minis.ledger.WIDGET_"+action).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widget);return PendingIntent.getBroadcast(c,widget*3+(action.equals("MODE")?1:2),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static void update(Context c,AppWidgetManager m,int widget,Map<String,long[]> totals,long now,Map<Boolean,BudgetUsage> budgets,LedgerDb db,long version,long state){
  boolean net=LedgerDb.prefs(c).getBoolean("widget_net_"+widget,false);BudgetUsage budget=budgets.get(net);if(budget==null){budget=BudgetUsage.read(c,db,now,net);budgets.put(net,budget);}int period=WidgetPeriods.valid(LedgerDb.prefs(c).getInt("widget_period_"+widget,0));String totalKey=period+"|"+net;long[] values=totals.get(totalKey);if(values==null){values=db.widgetTotals(now,period,net);totals.put(totalKey,values);}if(!work.current(version)||state!=selection.get())return;Bundle o=m.getAppWidgetOptions(widget);
  int width=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,240),height=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,124);boolean landscape=c.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;if(landscape){width=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,width);height=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,height);}boolean chart=WidgetSizing.chart(width,height);
  boolean dark=LedgerDb.prefs(c).getString("theme","light").equals("dark");RemoteViews v=new RemoteViews(c.getPackageName(),id(c,"layout",WidgetSizing.layout(width,height)));String suffix=dark?"_dark":"";applyTheme(c,v,dark);String mode=net?"净花销":"净支出";v.setTextViewText(id(c,"id","widget_mode"),mode+" ⇄");v.setTextViewText(id(c,"id","widget_amount"),"¥"+WidgetPeriods.money(values[2]));android.util.DisplayMetrics metrics=c.getResources().getDisplayMetrics();android.graphics.Paint amountPaint=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);amountPaint.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);float basePx=android.util.TypedValue.applyDimension(android.util.TypedValue.COMPLEX_UNIT_SP,36,metrics);amountPaint.setTextSize(basePx);amountPaint.setFontFeatureSettings("tnum");android.graphics.Paint.FontMetrics fm=amountPaint.getFontMetrics();v.setTextViewTextSize(id(c,"id","widget_amount"),android.util.TypedValue.COMPLEX_UNIT_PX,WidgetSizing.amountPx(width,metrics.density,amountPaint.measureText("¥-9999.99"),fm.descent-fm.ascent,basePx));v.setTextViewText(id(c,"id","widget_caption"),new String[]{"今日","本周","本月"}[period]);v.setOnClickPendingIntent(id(c,"id","widget_mode"),action(c,widget,"MODE"));String[] names={"day","week","month"};for(int i=0;i<3;i++){int view=id(c,"id","widget_"+names[i]);v.setInt(view,"setBackgroundResource",i==period?id(c,"drawable","widget_period_selected"+suffix):0);v.setTextColor(view,i==period?AppAppearance.accent(dark):AppAppearance.muted(dark));v.setOnClickPendingIntent(view,action(c,widget,"PERIOD_"+i));}
  v.setOnClickPendingIntent(id(c,"id","widget_amount"),PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(id(c,"id","widget_budget"),null);v.setOnClickPendingIntent(id(c,"id","widget_refresh"),action(c,widget,"REFRESH"));
  {String[][] prev={{"昨日","前日"},{"上周","前周"},{"上月","前月"}};v.setTextViewText(id(c,"id","widget_previous"),prev[period][0]+"  ¥"+WidgetPeriods.money(values[1]));v.setTextViewText(id(c,"id","widget_earlier"),prev[period][1]+"  ¥"+WidgetPeriods.money(values[0]));}
  v.setViewVisibility(id(c,"id","widget_history"),budget.visible()?android.view.View.GONE:android.view.View.VISIBLE);v.setViewVisibility(id(c,"id","widget_budget"),budget.visible()?android.view.View.VISIBLE:android.view.View.GONE);BudgetNative.bind(c,v,"widget_budget",budget,dark);
  if(chart){long[] starts=WidgetPeriods.bounds(now,period);String[] labels=new String[3];StringBuilder accessible=new StringBuilder();for(int i=0;i<3;i++){labels[i]=WidgetPeriods.label(starts[i],period);accessible.append(labels[i]).append(' ').append(mode).append(' ').append(WidgetPeriods.money(values[i])).append("元；");}v.setImageViewBitmap(id(c,"id","widget_chart"),WidgetChart.draw(values,labels,Math.max(240,Math.min(1000,WidgetSizing.chartWidth(width)*2)),Math.min(600,WidgetSizing.chartHeight(width,height)*2),dark));v.setContentDescription(id(c,"id","widget_chart"),accessible.toString());}if(work.current(version)&&state==selection.get())m.updateAppWidget(widget,v);
 }
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){dispatch(c);}
 public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int widget,Bundle options){dispatch(c);}
 public void onReceive(Context c,Intent i){String a=i.getAction();if(a!=null&&a.startsWith("me.minis.ledger.WIDGET_")){int widget=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);boolean exists=false;for(int id:AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,LedgerWidget.class)))if(id==widget)exists=true;if(!exists)return;selection.incrementAndGet();if(a.equals("me.minis.ledger.WIDGET_MODE")){String k="widget_net_"+widget;LedgerDb.prefs(c).edit().putBoolean(k,!LedgerDb.prefs(c).getBoolean(k,false)).apply();}else if(a.matches("me\\.minis\\.ledger\\.WIDGET_PERIOD_[012]")){LedgerDb.prefs(c).edit().putInt("widget_period_"+widget,a.charAt(a.length()-1)-'0').apply();}if(a.matches("me\\.minis\\.ledger\\.WIDGET_PERIOD_[012]")){RemoteViews feedback=new RemoteViews(c.getPackageName(),id(c,"layout",WidgetSizing.layout(0,0)));boolean dark=LedgerDb.prefs(c).getString("theme","light").equals("dark");for(int p=0;p<3;p++){int view=id(c,"id","widget_"+new String[]{"day","week","month"}[p]);boolean selected=p==a.charAt(a.length()-1)-'0';feedback.setInt(view,"setBackgroundResource",selected?id(c,"drawable","widget_period_selected"+(dark?"_dark":"")):0);feedback.setTextColor(view,selected?AppAppearance.accent(dark):AppAppearance.muted(dark));}AppWidgetManager.getInstance(c).partiallyUpdateAppWidget(widget,feedback);}dispatch(c);return;}super.onReceive(c,i);}
 private void dispatch(Context c){synchronized(LedgerWidget.class){if(pendingChange!=null){pendingChange.cancel(false);pendingChange=null;}}final PendingResult pending=goAsync();Context app=c.getApplicationContext();long state=selection.get();work.submit(v->updateAll(app,-1,v,state),pending==null?null:pending::finish);}
 public void onDeleted(Context c,int[] ids){for(int id:ids)LedgerDb.prefs(c).edit().remove("widget_net_"+id).remove("widget_period_"+id).apply();}
 public static String pin(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);if(Build.VERSION.SDK_INT>=26&&m.isRequestPinAppWidgetSupported()){return m.requestPinAppWidget(new ComponentName(c,LedgerWidget.class),null,null)?"已向桌面发出请求，不代表添加成功；若未弹出确认，请长按桌面 → 小部件 → 轻记":"桌面未接受添加请求，请长按桌面添加小部件";}return "当前桌面不支持应用直接添加，请长按桌面 → 小部件 → 轻记";}
}
